17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.service.ClinicService;
40	import org.springframework.samples.petclinic.util.BusinessDays;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    /** Maximum number of owners permitted in a single city; the create is rejected at this count. */
59	    private static final int CITY_CAPACITY = 50;
60	
61	    /** Maximum number of owners that may be created on a single day (by registrationDate); the
62	     * create is rejected once this many owners already carry today's registration date. */
63	    private static final int DAILY_REGISTRATION_LIMIT = 100;
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        // The effective registration date (supplied, or the server date when omitted) must fall on
114	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
115	        // registration date — the stored value, the per-day limit below and the membership number —
116	        // uses this adjusted date.
117	        LocalDate effectiveDate = BusinessDays.rollToBusinessDay(
118	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
119	        owner.setRegistrationDate(effectiveDate);
120	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
121	        // further creates for that day with 429 Too Many Requests.
122	        if (this.clinicService.countOwnersRegisteredOn(effectiveDate) >= DAILY_REGISTRATION_LIMIT) {
123	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
124	        }
125	        if (this.clinicService.isTelephoneInUse(owner.getTelephone())) {
126	            return new ResponseEntity<>(HttpStatus.CONFLICT);
127	        }
128	        // Per-city capacity: a city that already holds the maximum number of owners is full.
129	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
130	            return new ResponseEntity<>(HttpStatus.CONFLICT);
131	        }
132	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
133	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress());
134	        if (householdInUse) {
135	            if (!sharesHousehold) {
136	                return new ResponseEntity<>(HttpStatus.CONFLICT);
137	            }
138	            // Joining an existing household: assign the shared, stable household identifier to
139	            // the new owner (and back-fill the existing member(s)).
140	            this.clinicService.assignHousehold(owner);
141	        }
142	        owner.setNamesakeCount(
143	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
144	        this.clinicService.saveOwner(owner);
145	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
146	        headers.setLocation(UriComponentsBuilder.newInstance()
147	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
148	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
154	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
155	        if (currentOwner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        currentOwner.setAddress(ownerFieldsDto.getAddress());
159	        currentOwner.setCity(ownerFieldsDto.getCity());
160	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
161	        currentOwner.setLastName(ownerFieldsDto.getLastName());
162	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
163	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
164	        this.clinicService.saveOwner(currentOwner);
165	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Transactional
170	    @Override
171	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
172	        Owner owner = this.clinicService.findOwnerById(ownerId);
173	        if (owner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        this.clinicService.deleteOwner(owner);
177	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        HttpHeaders headers = new HttpHeaders();
188	        Pet pet = petMapper.toPet(petFieldsDto);
189	        owner.setId(ownerId);
190	        pet.setOwner(owner);
191	        pet.getType().setName(null);
192	        this.clinicService.savePet(pet);
193	        PetDto petDto = petMapper.toPetDto(pet);
194	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
195	            .buildAndExpand(pet.getId()).toUri());
196	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
202	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
203	        if (currentOwner != null) {
204	            Pet currentPet = this.clinicService.findPetById(petId);
205	            if (currentPet != null) {
206	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
207	                currentPet.setName(petFieldsDto.getName());
208	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
209	                this.clinicService.savePet(currentPet);
210	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
211	            }
212	        }
213	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
214	    }
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
219	        HttpHeaders headers = new HttpHeaders();
220	        Visit visit = visitMapper.toVisit(visitFieldsDto);
221	        Pet pet = new Pet();
222	        pet.setId(petId);
223	        visit.setPet(pet);
224	        this.clinicService.saveVisit(visit);
225	        VisitDto visitDto = visitMapper.toVisitDto(visit);
226	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
227	            .buildAndExpand(visit.getId()).toUri());
228	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
229	    }
230	
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Override
234	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
235	        Owner owner = this.clinicService.findOwnerById(ownerId);
